def _df_from(fixture, code):
    n = len(fixture)
    return pl.DataFrame({
        "code": [code] * n,
        "date": [date.fromisoformat(r[0]) for r in fixture],
        "open": [r[1] for r in fixture],
        "high": [r[2] for r in fixture],
        "low": [r[3] for r in fixture],
        "close": [r[4] for r in fixture],
        "volume": [float(r[5]) for r in fixture],
        "pre_close": [r[6] for r in fixture],
    })


def _run_selector(df, market_cap):
    defn = make_super_b1_defn()
    sel = defn.selector_class(defn)
    warmup = sel.warmup(df)
    ctx = SelectionContext(
        trade_date=df["date"].max(),
        market_data=df,
        candidate_codes=df["code"].unique().to_list(),
        market_cap=market_cap,
    )
    return sorted(sel.select_day(ctx, warmup).selected_codes)


def _reference_hit(df):
    """朴素逐行实现：每只股票最后一天 XG 是否命中。"""
    def ema(seq, n):
        a = 2 / (n + 1); y = [seq[0]]
        for t in range(1, len(seq)):
            y.append(a * seq[t] + (1 - a) * y[-1])
        return y

    def ma(seq, n):
        return [sum(seq[max(0, i - n + 1):i + 1]) / len(seq[max(0, i - n + 1):i + 1]) for i in range(len(seq))]

    def count(seq, n):
        return [sum(1 for x in seq[max(0, i - n + 1):i + 1] if x) for i in range(len(seq))]

    out = {}
    for g in df.partition_by("code"):
        code = g["code"][0]
        g = g.sort("date")
        cs, os_, hs, ls, vs = (g[c].to_list() for c in ("close", "open", "high", "low", "volume"))
        pcs = g["pre_close"].to_list()
        prev_v = [None] + vs[:-1]
        n = len(cs); i = n - 1

        st = ema(ema(cs, 10), 10)
        life = [sum(m) / len(m) for m in zip(*[ma(cs, w) for w in (14, 28, 57, 114)])]
        amp = (hs[i] - ls[i]) / pcs[i] * 100
        inc = (cs[i] - pcs[i]) / pcs[i] * 100
        dif = [e12 - e26 for e12, e26 in zip(ema(cs, 12), ema(cs, 26))]
        dea = ema(dif, 9)
        vd = [pv is not None and v > 2 * pv for v, pv in zip(vs, prev_v)]
        pull = abs(cs[i] - life[i]) / life[i] <= 0.016

        out[code] = bool(
            amp < 7 and inc < 2 and cs[i] > ma(cs, 60)[i]
            and dif[i] > dea[i] and count(vd, 120)[i] >= 1
            and st[i] > life[i] and pull
        )
    return out


def test_real_fixture_matches_reference():
    """真实行情：002043 公式命中、000001 不命中；selector 与参考一致。"""
    df = pl.concat([_df_from(_FIXTURE_HIT, "002043"), _df_from(_FIXTURE_MISS, "000001")])
    ref = _reference_hit(df)
    assert ref["002043"] is True, "真实样本 002043 应命中公式"
    assert ref["000001"] is False, "真实样本 000001 应不命中"
    assert _run_selector(df, {"002043": 600000.0, "000001": 600000.0}) == ["002043"]


def test_mvok_strict_above_50_yi():
    """公式 市值>50（严格大于）：恰好 50 亿不入选，50 亿以上入选。"""
    df = _df_from(_FIXTURE_HIT, "002043")
    assert _run_selector(df, {"002043": 499999.0}) == []
    assert _run_selector(df, {"002043": 500000.0}) == []   # 恰好 50 亿 → >50 不成立
    assert _run_selector(df, {"002043": 500001.0}) == ["002043"]


def test_requires_market_cap_flag():
    defn = make_super_b1_defn()
    assert defn.selector_class.REQUIRES_MARKET_CAP is True
